// Hand-written bridge between the `uni-data-value` envelope a Mudu host
// passes across the procedure byte pipe and the positional wire-value model
// of the mgen-generated Go codecs (the files carrying the "Generated by
// mudu_gen" header).
//
// A user-defined record argument travels as a UniDataValue record case:
// field entries in WIT declaration order, field names possibly empty (the
// host drops them — positional semantics). RecordFieldValues unwraps that
// envelope into the integer-keyed map (1-based field numbers) the generated
// XxxFromValue decoders consume; RecordFromFieldValues is the symmetric
// wrap for record return values, emitting empty field names like the host
// does.
//
// The host's transactable scalar vocabulary (mudu_binding's
// `uni_to`/`uni_from`) has no Bool/U8..U32/U64 cases: booleans cross as i32
// (0/1 — the desc declares them I32, the same family the procedure scalar
// table uses), unsigned 8-32-bit integers as i32, and u64 as i64. The
// bridge performs exactly those mappings, so the generated codecs see the
// plain Go values they expect and the host always receives scalar cases it
// accepts.
//
// TinyGo-compatible: no unsafe, no generics, no reflection.
package types

import (
	"fmt"

	"github.com/ybbh/mududb_p/bindings/go/codec"
)

// RecordFieldValues unwraps a UniDataValue record-case envelope into the
// integer-keyed field map (position i becomes key uint64(i+1), the WIT
// declaration order) the mgen-generated record decoders (XxxFromValue)
// consume. Field values convert to the plain wire-value model recursively
// (nested records become nested maps, arrays become []any, the Null scalar
// becomes nil). A non-record input is an error. Decode stays lenient end to
// end: the generated decoder skips field numbers it does not declare and
// defaults the missing ones.
//
// The input rides as `any` — the same shape the generated XxxFromValue
// codecs take — so a decoded procedure parameter (held as `any` by the
// guest's param list) feeds straight in without a cast helper.
func RecordFieldValues(v any) (map[uint64]any, error) {
	uv, ok := v.(UniDataValue)
	if !ok {
		return nil, fmt.Errorf("expected a UniDataValue record, got %T", v)
	}
	record, ok := uv.(UniDataValueRecord)
	if !ok {
		return nil, fmt.Errorf("expected a UniDataValue record, got %T", v)
	}
	out := make(map[uint64]any, len(record.Inner))
	for i, field := range record.Inner {
		value, err := wireValueFromDatum(field.FieldValue)
		if err != nil {
			return nil, fmt.Errorf("record field %d: %w", i+1, err)
		}
		out[uint64(i+1)] = value
	}
	return out, nil
}

// RecordFromFieldValues wraps the positional field values of a record into
// the UniDataValue record-case envelope (field names empty — the wire is
// positional). The input is either the integer-keyed map produced by the
// mgen-generated XxxToValue encoders (1-based field numbers; a missing
// slot, e.g. an omitted option field, encodes as the Null scalar so
// declaration positions are preserved — note that trailing omitted slots
// cannot be recovered and shrink the record) or a plain positional slice.
// Field values convert to the host's transactable scalar vocabulary (see
// the package comment above).
func RecordFromFieldValues(values any) (UniDataValue, error) {
	var positional []any
	switch v := values.(type) {
	case map[uint64]any:
		positional = flattenFieldMap(v)
	case []any:
		positional = v
	default:
		return nil, fmt.Errorf("expected map[uint64]any or []any record field values, got %T", values)
	}
	fields := make([]UniDataValueField, len(positional))
	for i, value := range positional {
		datum, err := datumFromWireValue(value)
		if err != nil {
			return nil, fmt.Errorf("record field %d: %w", i+1, err)
		}
		fields[i] = UniDataValueField{FieldName: "", FieldValue: datum}
	}
	return UniDataValueRecord{Inner: fields}, nil
}

// flattenFieldMap renders a 1-based field map as the positional slice of
// slots 1..maxKey; absent slots (omitted option fields) stay nil. Key 0 is
// not a valid field number and is skipped.
func flattenFieldMap(m map[uint64]any) []any {
	var max uint64
	for k := range m {
		if k > max {
			max = k
		}
	}
	out := make([]any, max)
	for k, v := range m {
		if k == 0 {
			continue
		}
		out[k-1] = v
	}
	return out
}

// wireValueFromDatum converts a UniDataValue to its plain wire value in the
// mgen codec value model (the shape an XxxFromValue decoder expects for the
// corresponding field type).
func wireValueFromDatum(uv UniDataValue) (any, error) {
	switch v := uv.(type) {
	case UniDataValueScalar:
		return wireValueFromScalar(v.Inner)
	case UniDataValueArray:
		out := make([]any, len(v.Inner))
		for i, item := range v.Inner {
			value, err := wireValueFromDatum(item)
			if err != nil {
				return nil, err
			}
			out[i] = value
		}
		return out, nil
	case UniDataValueRecord:
		return RecordFieldValues(v)
	case UniDataValueBinary:
		return v.Inner, nil
	default:
		return nil, fmt.Errorf("unknown UniDataValue kind %T", uv)
	}
}

// wireValueFromScalar converts a UniScalarValue to its plain wire value.
// Unsigned integers surface as uint64, signed as int64 — the checked
// conversions of the generated decoders accept every width (range-checked
// against the declared field type).
func wireValueFromScalar(sv UniScalarValue) (any, error) {
	switch v := sv.(type) {
	case UniScalarValueBool:
		return v.Inner, nil
	case UniScalarValueU8:
		return uint64(v.Inner), nil
	case UniScalarValueU16:
		return uint64(v.Inner), nil
	case UniScalarValueU32:
		return uint64(v.Inner), nil
	case UniScalarValueU64:
		return v.Inner, nil
	case UniScalarValueI8:
		return int64(v.Inner), nil
	case UniScalarValueI16:
		return int64(v.Inner), nil
	case UniScalarValueI32:
		return int64(v.Inner), nil
	case UniScalarValueI64:
		return v.Inner, nil
	case UniScalarValueU128:
		return v.Inner, nil
	case UniScalarValueI128:
		return v.Inner, nil
	case UniScalarValueF32:
		// the F32 marker keeps the single-precision wire semantics through
		// the plain value model
		return codec.F32(v.Inner), nil
	case UniScalarValueF64:
		return v.Inner, nil
	case UniScalarValueChar:
		return v.Inner, nil
	case UniScalarValueString:
		return v.Inner, nil
	case UniScalarValueNumeric:
		return v.Inner, nil
	case UniScalarValueDate:
		return v.Inner, nil
	case UniScalarValueTime:
		return v.Inner, nil
	case UniScalarValueTimestamp:
		return v.Inner, nil
	case UniScalarValueTimestampTz:
		return v.Inner, nil
	case UniScalarValueBlob:
		return v.Inner, nil
	case UniScalarValueNull:
		return nil, nil
	default:
		return nil, fmt.Errorf("unknown UniScalarValue kind %T", sv)
	}
}

// datumFromWireValue converts a plain wire value (as produced by the
// mgen-generated XxxToValue encoders) to a UniDataValue in the host's
// transactable vocabulary: booleans and sub-32-bit integers become I32,
// 64-bit integers become I64, and every composite shape recurses.
func datumFromWireValue(v any) (UniDataValue, error) {
	switch value := v.(type) {
	case nil:
		return UniDataValueScalar{Inner: UniScalarValueNull{}}, nil
	case bool:
		// the host vocabulary has no Bool: booleans cross as i32 (0/1)
		var n int32
		if value {
			n = 1
		}
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: n}}, nil
	case uint8:
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: int32(value)}}, nil
	case uint16:
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: int32(value)}}, nil
	case uint32:
		if value > 2147483647 {
			return nil, fmt.Errorf("u32 value %d overflows the host i32 vocabulary", value)
		}
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: int32(value)}}, nil
	case uint64:
		if value > 9223372036854775807 {
			return nil, fmt.Errorf("u64 value %d overflows the host i64 vocabulary", value)
		}
		return UniDataValueScalar{Inner: UniScalarValueI64{Inner: int64(value)}}, nil
	case uint:
		return datumFromWireValue(uint64(value))
	case int8:
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: int32(value)}}, nil
	case int16:
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: int32(value)}}, nil
	case int32:
		return UniDataValueScalar{Inner: UniScalarValueI32{Inner: value}}, nil
	case int64:
		return UniDataValueScalar{Inner: UniScalarValueI64{Inner: value}}, nil
	case int:
		return datumFromWireValue(int64(value))
	case float32:
		return UniDataValueScalar{Inner: UniScalarValueF32{Inner: value}}, nil
	case codec.F32:
		return UniDataValueScalar{Inner: UniScalarValueF32{Inner: float32(value)}}, nil
	case float64:
		return UniDataValueScalar{Inner: UniScalarValueF64{Inner: value}}, nil
	case string:
		return UniDataValueScalar{Inner: UniScalarValueString{Inner: value}}, nil
	case []byte:
		return UniDataValueScalar{Inner: UniScalarValueBlob{Inner: value}}, nil
	case []any:
		items := make([]UniDataValue, len(value))
		for i, item := range value {
			datum, err := datumFromWireValue(item)
			if err != nil {
				return nil, err
			}
			items[i] = datum
		}
		return UniDataValueArray{Inner: items}, nil
	case map[uint64]any:
		return RecordFromFieldValues(value)
	default:
		return nil, fmt.Errorf("unsupported record field value type %T", v)
	}
}
